window.docContents[220].resolve({"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Concrete-Lie-algebra-examples-_LPAR_continued_RPAR____-aff_LPAR_1_RPAR____-so_LPAR_n_RPAR_/#Chapter2___Discussion_concrete_Lie_examples_continued":{"contents":"(4) The algebra \\operatorname{aff}(1) of matrices \\begin{pmatrix} * & * \\\\ 0 & 0 \\end{pmatrix}.\nIts basis consists of X = \\begin{pmatrix} 1 & 0 \\\\ 0 & 0 \\end{pmatrix} and Y = \\begin{pmatrix} 0 & 1 \\\\ 0 & 0 \\end{pmatrix}, with [X, Y] = Y.\n\n(5) \\mathfrak{so}(n), the space of skew-symmetric n \\times n matrices, with [a, b] = ab - ba.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.9. Lie algebras\tConcrete Lie algebra examples (continued): aff(1), so(n)","header":"Concrete Lie algebra examples (continued): aff(1), so(n)","id":"/2___-Basic-notions-of-representation-theory/2___9___-Lie-algebras/Concrete-Lie-algebra-examples-_LPAR_continued_RPAR____-aff_LPAR_1_RPAR____-so_LPAR_n_RPAR_/#Chapter2___Discussion_concrete_Lie_examples_continued"},"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/#chapter-04___section-4-1":{"contents":"\n\n\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t4. Representations of finite groups: Basic results","header":"4.1. Maschke's theorem","id":"/4___-Representations-of-finite-groups___-Basic-results/4___1___-Maschke___s-theorem/#chapter-04___section-4-1"},"/6___-Quiver-representations/6___2___-Indecomposable-representations-of-the-quivers-___A_1______-___A_2______-___A_3___/Section-6___2-heading-and-introduction/#Chapter6___Section6___2_heading":{"contents":"\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.2. Indecomposable representations of the quivers $A_1$, $A_2$, $A_3$\tSection 6.2 heading and introduction","header":"Section 6.2 heading and introduction","id":"/6___-Quiver-representations/6___2___-Indecomposable-representations-of-the-quivers-___A_1______-___A_2______-___A_3___/Section-6___2-heading-and-introduction/#Chapter6___Section6___2_heading"},"/7___-Introduction-to-categories/7___5___-Representable-functors/Yoneda-Lemma/#Chapter7___Lemma7___5___1":{"contents":"Lemma 7.5.1 (The Yoneda Lemma). If a functor F is represented by an object X, then X is unique up to a unique isomorphism. I.e., if X, Y are two objects in \\mathcal{C}, then for any isomorphism of functors\n\\phi : \\operatorname{Hom}(X, ?) \\to \\operatorname{Hom}(Y, ?) there is a unique isomorphism a_\\phi : X \\to Y inducing \\phi.\n\nProof (Sketch). One sets a_\\phi = \\phi_Y^{-1}(1_Y) and shows that it is invertible by constructing the inverse, which is a_\\phi^{-1} = \\phi_X(1_X). It remains to show that the composition both ways is the identity, which we will omit here. This establishes the existence of a_\\phi. Its uniqueness is verified in a straightforward manner. \\square\n\n\n\n","context":"Introduction to Representation Theory\t7. Introduction to categories\t7.5. Representable functors\tYoneda Lemma","header":"Yoneda Lemma","id":"/7___-Introduction-to-categories/7___5___-Representable-functors/Yoneda-Lemma/#Chapter7___Lemma7___5___1"}});
